CREATE TABLE ticket_event(id VARCHAR(36) PRIMARY KEY,department_id BIGINT NOT NULL,name VARCHAR(120) NOT NULL,name_en VARCHAR(120) NOT NULL,venue VARCHAR(120) NOT NULL,venue_en VARCHAR(120) NOT NULL,description VARCHAR(3000) NOT NULL,description_en VARCHAR(3000) NOT NULL,category VARCHAR(20) NOT NULL,currency VARCHAR(3) NOT NULL,starts_at BIGINT NOT NULL,sale_starts_at BIGINT NOT NULL,sale_ends_at BIGINT NOT NULL,refund_ends_at BIGINT NOT NULL,state VARCHAR(20) NOT NULL,version BIGINT NOT NULL,FOREIGN KEY(department_id) REFERENCES department(id),CHECK(state IN ('DRAFT','PUBLISHED','CLOSED')));
CREATE TABLE event_staff(event_id VARCHAR(36) NOT NULL,account_id BIGINT NOT NULL,PRIMARY KEY(event_id,account_id),FOREIGN KEY(event_id) REFERENCES ticket_event(id),FOREIGN KEY(account_id) REFERENCES account(id));
CREATE TABLE ticket_type(id BIGINT AUTO_INCREMENT PRIMARY KEY,event_id VARCHAR(36) NOT NULL,name VARCHAR(60) NOT NULL,name_en VARCHAR(60) NOT NULL,prefix VARCHAR(5) NOT NULL,price BIGINT NOT NULL,capacity INT NOT NULL,columns INT NOT NULL,version BIGINT NOT NULL,UNIQUE(event_id,prefix),FOREIGN KEY(event_id) REFERENCES ticket_event(id),CHECK(price>=0),CHECK(capacity>0),CHECK(columns>0));
CREATE TABLE ticket_checkout(booking_id VARCHAR(36) PRIMARY KEY,session_id VARCHAR(100) UNIQUE,payment_intent VARCHAR(100),url VARCHAR(2000),mode VARCHAR(20) NOT NULL,created_at BIGINT NOT NULL,FOREIGN KEY(booking_id) REFERENCES ticket_booking(id));
CREATE TABLE refund_task(id VARCHAR(36) PRIMARY KEY,booking_id VARCHAR(36) NOT NULL,payment_intent VARCHAR(100) NOT NULL UNIQUE,amount BIGINT NOT NULL,currency VARCHAR(3) NOT NULL,mode VARCHAR(20) NOT NULL,state VARCHAR(20) NOT NULL,refund_id VARCHAR(100),releases_seat BOOLEAN NOT NULL,attempts INT NOT NULL,generation INT NOT NULL,next_attempt BIGINT NOT NULL,error VARCHAR(40) NOT NULL,FOREIGN KEY(booking_id) REFERENCES ticket_booking(id),CHECK(amount>=0));
CREATE TABLE mail_task(id VARCHAR(36) PRIMARY KEY,booking_id VARCHAR(36) NOT NULL,recipient VARCHAR(254) NOT NULL,state VARCHAR(20) NOT NULL,attempts INT NOT NULL,next_attempt BIGINT NOT NULL,error VARCHAR(40) NOT NULL,FOREIGN KEY(booking_id) REFERENCES ticket_booking(id));
CREATE INDEX ix_refund_due ON refund_task(state,next_attempt);
CREATE INDEX ix_mail_due ON mail_task(state,next_attempt);
CREATE INDEX ix_booking_owner ON ticket_booking(owner_id);
